#' Plot population distribution
#' 
#' This function plots the distribution of the population across space at a given time. To plot population distribution \emph{over} time see \code{\link{plot.pop.dyn}}.
#' 
#' @export
#' 
#' @param x Vector defining the spatial context. The y values generated by \code{create.kernel.params} are a good example.
#' @param pop Vector of population sizes in space. This can a single column from an output of the function \code\{\link{runIPM}}.
#' @param col Colour of the line
#' @param new.plot Deafult is \code{TRUE.} Defines whether the line should be overlaid to an existing plot (\code{FALSE}), or whether a new one should be generated (\code{TRUE})
#' 

draw.pop.distr <- function(x, pop, col, new.plot=T){
  
  # drawing a new emtpy plot only if requested
  if(new.plot){
    plot(0, xlim=c(min(x), max(x)), ylim=c(0, max(pop)), col='white')
  }
  
  # now drawing the line
  lines(pop~x, col=col)
}
